import React, { useEffect, useState } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ onBuy, purchasedItems = {} }) { // Default to empty object
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 1. Get User ID from Token
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        // Ensure we capture the ID regardless of naming convention
        const userId = decoded.id || decoded.userId || decoded._id;
        setCurrentUserId(userId);
      } catch (err) {
        console.error("Invalid token:", err);
      }
    }

    // 2. Fetch Books
    setLoading(true);
    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => setItems(data))
      .catch((err) => console.error("Error fetching books:", err))
      .finally(() => setLoading(false));
  }, []);

  // Filter items: Exclude books where the item's userId matches current user
  const filteredItems = items.filter((item) => {
    if (!currentUserId) return true;
    const itemOwnerId = item.userId || item.user || item._ownerId; // be flexible here too
    return String(itemOwnerId) !== String(currentUserId);
  });

  if (loading) {
    return (
      <>
        <Navbar />
        <div className="Body"><div className="HeadMo"><h1>Loading...</h1></div></div>
        <Footer />
      </>
    );
  }

  return (
    <>
      <Navbar />
      <div className="Body">
        {filteredItems.length === 0 ? (
          <div className="HeadMo"><h1>No books available!</h1></div>
        ) : (
          filteredItems.map((item) => {
            // Check for both 'id' and '_id' to prevent undefined keys
            const itemId = item.id || item._id;
            const isPurchased = !!purchasedItems[itemId];

            return (
              <Card
                key={itemId}
                pic={item.pic}
                title={item.title}
                para={item.para}
                price={item.price}
              >
                <button
                  onClick={() => onBuy(item)}
                  disabled={isPurchased}
                  style={{
                    backgroundColor: isPurchased ? "grey" : "#0d6efc",
                    color: "#fff",
                    borderRadius: "5px",
                    padding: "10px",
                    cursor: isPurchased ? "not-allowed" : "pointer",
                    width: "130px",
                    border: "none"
                  }}
                >
                  {isPurchased ? "In Cart" : "Add to Cart"}
                </button>
              </Card>
            );
          })
        )}
      </div>
      <Footer />
    </>
  );
}

export default Shop;
